68384153-14f4-4f16-a267-cb5e6c021532	c4a717d2-ff95-47e1-a6ec-c1a2abd1f512	AdaptiveBlock	block:1	{"blockIndex":1,"band":2,"production":[{"id":"s1","kind":"sentence","wordId":"3a5ab735-16d9-4ead-adaa-a33544362ccb","targetWord":"no big deal","scenarioKey":null,"scenarioZh":"","prompt":"\\u7528\\u300Cno big deal\\u300D\\u9020\\u4E00\\u4E2A\\u82F1\\u6587\\u53E5\\u5B50\\u3002","intrinsicScore":25},{"id":"s2","kind":"sentence","wordId":"fe9a8741-ac4f-43d1-be5f-beff6b1e414d","targetWord":"nice one","scenarioKey":null,"scenarioZh":"","prompt":"\\u7528\\u300Cnice one\\u300D\\u9020\\u4E00\\u4E2A\\u82F1\\u6587\\u53E5\\u5B50\\u3002","intrinsicScore":25},{"id":"e1","kind":"scenario","wordId":null,"targetWord":null,"scenarioKey":"payment_services","scenarioZh":"\\u4ED8\\u6B3E\\u4E0E\\u529E\\u4E8B","prompt":"\\u60C5\\u5883\\u8868\\u8FBE\\uFF1A\\u5728\\u300C\\u4ED8\\u6B3E\\u4E0E\\u529E\\u4E8B\\u300D\\u573A\\u666F\\u4E0B\\uFF0C\\u7528\\u82F1\\u8BED\\u5199 2\\u20133 \\u53E5\\u4F60\\u7684\\u5E94\\u5BF9\\u6216\\u611F\\u53D7\\u3002","intrinsicScore":0}],"vocabulary":[{"id":"v1","word":"alarm","options":["\\u5BB3\\u6015\\u7684","\\u7ACB\\u573A","\\u95F9\\u949F","\\u51FA\\u53D1\\uFF1B\\u5F00\\u59CB\\u505A\\u67D0\\u4E8B"],"correctIndex":2,"intrinsicScore":25}],"reading":{"id":"r1","articleId":"fc1bc003-fec6-4795-9f44-27c398485120","title":"Rainy Day Indoors","content":"When it rains heavily, we stay indoors and find quiet activities. I listen to the sound of rain on the window and read a book. My sister draws pictures at the table. My father makes tea and plays soft music in the living room. We do not feel bored because we plan small projects together. Sometimes we bake simple cookies in the kitchen. Rainy days remind us to slow down and enjoy time at home. The streets outside look shiny and empty. When the rain stops, the air feels fresh and cool. I like both sunny days and peaceful rainy afternoons.","wordCount":101,"question":"\\u6587\\u4E2D \\u0022do\\u0022 \\u7684\\u542B\\u4E49\\u662F\